#include <unordered_map>
#include <string>
#include <fstream>
#include <cstdint>

void write_huffman_dictionary(std::ofstream &outfile, const std::unordered_map<unsigned char, std::string> &huffman_codes) {
    uint32_t dict_size = static_cast<uint32_t>(huffman_codes.size());
    outfile.write(reinterpret_cast<const char*>(&dict_size), sizeof(dict_size));
    for (const auto &pair : huffman_codes) {
        unsigned char symbol = pair.first;
        const std::string &code = pair.second;
        uint8_t len = static_cast<uint8_t>(code.size());
        outfile.write(reinterpret_cast<const char*>(&symbol), sizeof(symbol));
        outfile.write(reinterpret_cast<const char*>(&len), sizeof(len));
        if (!code.empty()) {
            outfile.write(code.data(), len);
        }
    }
}

int main(){
    std::unordered_map<unsigned char, std::string> map{{'a',"01"},{'b',"10"}};
    std::ofstream out("test.bin", std::ios::binary);
    write_huffman_dictionary(out, map);
    out.close();
    // read back to verify
    std::ifstream in("test.bin", std::ios::binary);
    uint32_t size; in.read(reinterpret_cast<char*>(&size), sizeof(size));
    for(uint32_t i=0;i<size;++i){
        unsigned char c; uint8_t l; in.read(reinterpret_cast<char*>(&c),1); in.read(reinterpret_cast<char*>(&l),1);
        std::string code(l,' '); in.read(&code[0], l);
        // print
        std::cout<<c<<":"<<code<<"\n";
    }
    return 0;
}

